import re
from typing import List, Dict, Any, Tuple, Union

# ------------------------------------------------------------------
# Helper functions are assumed to be available in the environment:
# node_by_title(doc, title) -> node dict
# node_by_id(doc, node_id) -> node dict
# children(doc, node) -> list of child nodes
# scope_nodes(doc, scope) -> list of scope child nodes
# table_rows(node) -> list of (row_index, {column: cell}) for a table node
# ------------------------------------------------------------------


def _find_child(node: Dict[str, Any], suffix: str) -> Union[Dict[str, Any], None]:
    """Return the first child node whose title ends with the given suffix."""
    for child in children(node, node):
        if child.get("title", "").endswith(suffix):
            return child
    return None


def entities(doc: Dict[str, Any], scope: str) -> List[Dict[str, str]]:
    """
    Return all entities in the given scope (video). Each entity has an id
    (object number as string) and a human‑readable description.
    """
    video_node = node_by_title(doc, scope)
    objects_node = _find_child(video_node, ": Objects")
    if objects_node is None:
        return []

    result = []
    for line in objects_node.get("lines", []):
        # Example line: "Object 0: brown metal sphere (color=brown, material=metal, shape=sphere)"
        m = re.match(r"Object (\d+): ([^()]+)(?:\s*\(.*\))?", line)
        if m:
            obj_id, description = m.group(1), m.group(2).strip()
            result.append({"id": obj_id, "description": description})
    return result


def recorded_end(doc: Dict[str, Any], scope: str) -> Union[float, None]:
    """
    Return the last frame number covered by the scope.  None if the scope
    has no time information.
    """
    video_node = node_by_title(doc, scope)
    max_frame = -1
    # Check events section
    events_node = _find_child(video_node, ": Events")
    if events_node:
        for line in events_node.get("lines", []):
            m = re.match(r"Frame (\d+):", line)
            if m:
                frame = int(m.group(1))
                if frame > max_frame:
                    max_frame = frame
    # Check motion log
    motion_node = _find_child(video_node, ": Motion log")
    if motion_node:
        for _, row in table_rows(motion_node):
            frame = int(row.get("frame", -1))
            if frame > max_frame:
                max_frame = frame
    return max_frame if max_frame >= 0 else None


def _parse_motion_rows(motion_node: Dict[str, Any]) -> Tuple[List[Tuple[int, Dict[str, Any]]], Dict[str, List[Tuple[int, Dict[str, Any]]]]:
    """
    Parse the motion log table and return:
    - list of (row_index, row_dict) for all rows
    - mapping from object id to list of (row_index, row_dict) sorted by frame
    """
    rows = []
    obj_map: Dict[str, List[Tuple[int, Dict[str, Any]]]] = {}
    for r_index, row in table_rows(motion_node):
        # Convert numeric columns to float/int
        parsed = {}
        for col, val in row.items():
            try:
                if '.' in val:
                    parsed[col] = float(val)
                else:
                    parsed[col] = int(val)
            except Exception:
                parsed[col] = val
        rows.append((r_index, parsed))
        obj_id = str(parsed.get("object", "").split()[0])  # object column like "1 blue metal cube"
        obj_map.setdefault(obj_id, []).append((r_index, parsed))
    # Sort lists by frame
    for lst in obj_map.values():
        lst.sort(key=lambda x: x[1]["frame"])
    return rows, obj_map


